@@ -2,7 +2,7 @@
 ----------------

 ### v1.18.25 "Edgy Guinea Pig"
-* No new changes since the release of v1.18.24
+* BUGFIX: `@UtilityClass` no longer causes javac to crash when generic method calls and overloaded methods use a nested class.

 ### v1.18.24 (April 18th, 2022)

PATCH
ant test.compile test.javacCurrent > build/utilityclass-fixed.log 2>&1; result=$?; grep -E '\[ERR\]|\[FAIL\]|UtilityClassGeneric|Compiling|BUILD (SUCCESSFUL|FAILED)' build/utilityclass-fixed.log; tail -4 build/utilityclass-fixed.log; exit "$result"

cd /testbed && patch -p1 <<'PATCH'
--- a/src/stubs/com/sun/tools/javac/code/Symbol.java
+++ b/src/stubs/com/sun/tools/javac/code/Symbol.java
@@ -24,4 +24,5 @@
 public abstract class Symbol implements Element {
 	public Type type;
+	public Type erasure_field;
 	public Name name;
 	public Symbol owner;
PATCH
ant test.compile test.javacCurrent > build/utilityclass-fixed.log 2>&1; result=$?; grep -E '\[ERR\]|\[FAIL\]|UtilityClassGeneric|Compiling|BUILD (SUCCESSFUL|FAILED)' build/utilityclass-fixed.log; tail -4 build/utilityclass-fixed.log; exit "$result"

